    ProfileModule,
    AdminModule,
  ],
})
export class AppModule {}

import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { RoleEnum } from '../enums/role.enum';

export interface CurrentUserPayload {
  id: string;
  role: RoleEnum;
  email?: string;
}

export const CurrentUser = createParamDecorator(
  (property: keyof CurrentUserPayload | undefined, context: ExecutionContext) => {
    const request = context.switchToHttp().getRequest<{ user?: CurrentUserPayload }>();
    return property ? request.user?.[property] : request.user;
  },
);

import { SetMetadata } from '@nestjs/common';
import { ROLES_METADATA_KEY } from '../constants/roles.constant';
import { RoleEnum } from '../enums/role.enum';

export const Roles = (...roles: RoleEnum[]) => SetMetadata(ROLES_METADATA_KEY, roles);

import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { Request, Response } from 'express';

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse<Response>();
    const request = context.getRequest<Request>();
    const status = exception instanceof HttpException
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;
    const message = exception instanceof HttpException
      ? exception.getResponse()
      : 'Internal server error';

    response.status(status).json({
      statusCode: status,
      message,
      path: request.url,
      timestamp: new Date().toISOString(),
    });
  }
}

import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_METADATA_KEY } from '../constants/roles.constant';
import { RoleEnum } from '../enums/role.enum';
import { CurrentUserPayload } from '../decorators/current-user.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const roles = this.reflector.getAllAndOverride<RoleEnum[]>(ROLES_METADATA_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (!roles?.length) return true;

    const request = context.switchToHttp().getRequest<{ user?: CurrentUserPayload }>();
    return !!request.user && roles.includes(request.user.role);
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';

@Injectable()
export class ResponseInterceptor implements NestInterceptor {
  intercept(_context: ExecutionContext, next: CallHandler): Observable<unknown> {
    return next.handle();
  }
}

export interface PaginationOptions {
  page: number;
  limit: number;
}

export function normalizePagination(
  page?: string | number,
  limit?: string | number,
): PaginationOptions {
  const parsedPage = Number(page ?? 1);
  const parsedLimit = Number(limit ?? 20);

  return {
    page: Number.isInteger(parsedPage) && parsedPage > 0 ? parsedPage : 1,
    limit: Number.isInteger(parsedLimit) && parsedLimit > 0
      ? Math.min(parsedLimit, 100)
      : 20,
  };
}

import { registerAs } from '@nestjs/config';

const apiBaseUrl =
  process.env.WHATSAPP_API_BASE_URL ??
  process.env.WHATSAPP_API_URL ??
  'https://graph.facebook.com';

const apiVersion = process.env.WHATSAPP_API_VERSION ?? 'v21.0';

export default registerAs('whatsapp', () => ({
  apiBaseUrl,
  apiVersion,
  apiUrl: `${apiBaseUrl.replace(/\/+$/, '')}/${apiVersion.replace(/^\/+/, '')}`,
  phoneNumberId: process.env.WHATSAPP_PHONE_NUMBER_ID,
  token: process.env.WHATSAPP_ACCESS_TOKEN ?? process.env.WHATSAPP_TOKEN,
  verifyToken: process.env.WHATSAPP_WEBHOOK_VERIFY_TOKEN ?? process.env.WHATSAPP_VERIFY_TOKEN,
  appSecret: process.env.WHATSAPP_APP_SECRET,
}));

import { NestFactory } from '@nestjs/core';
import { ValidationPipe } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from './app.module';
import { HttpExceptionFilter } from './common/filters/http-exception.filter';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, { rawBody: true });
  const configService = app.get(ConfigService);

  app.setGlobalPrefix(configService.get<string>('app.apiPrefix', 'api/v1'));
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      forbidNonWhitelisted: true,
    }),
  );
  app.useGlobalFilters(new HttpExceptionFilter());
  app.enableCors({
    origin: configService.get<string>('FRONTEND_URL')?.split(',').map((origin) => origin.trim()) ?? true,
    credentials: true,
  });
  app.enableShutdownHooks();

  const swaggerConfig = new DocumentBuilder()
    .setTitle('XeuySil API')
    .setDescription('API REST de la plateforme XeuySil')
    .setVersion('1.0.0')
    .addBearerAuth()
    .build();
  const document = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('docs', app, document, { useGlobalPrefix: false });

  await app.listen(configService.get<number>('app.port', 3000));
}

bootstrap();

import { GUARDS_METADATA } from '@nestjs/common/constants';
import { RoleEnum } from '@prisma/client';
import type { CurrentUserPayload } from '../../common/decorators/current-user.decorator';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { AdminController } from './admin.controller';
import { AdminGuard } from './admin.guard';
import { AdminService } from './admin.service';
import { AdminUserQueryDto } from './dto/admin-query.dto';

describe('AdminController', () => {
  const adminService = {
    listUsers: jest.fn(),
    getUser: jest.fn(),
    updateUserStatus: jest.fn(),
    updatePremium: jest.fn(),
    listMissions: jest.fn(),
    getMission: jest.fn(),
    getMissionStats: jest.fn(),
    listCommissions: jest.fn(),
    getCommissionStats: jest.fn(),
    getRestrictedWorkers: jest.fn(),
    listJobs: jest.fn(),
    createJob: jest.fn(),
    updateJob: jest.fn(),
    deleteJob: jest.fn(),
    listZones: jest.fn(),
    createZone: jest.fn(),
    updateZone: jest.fn(),
    deleteZone: jest.fn(),
    getSettings: jest.fn(),
    patchSettings: jest.fn(),
    getPlatformStats: jest.fn(),
    updateMissionStatus: jest.fn(),
  };
  let controller: AdminController;

  beforeEach(() => {
    jest.clearAllMocks();
    controller = new AdminController(adminService as unknown as AdminService);
  });

  it('passes user filters to the service', () => {
    const query: AdminUserQueryDto = { page: 2, limit: 10, premium: true, nom: 'Awa' };
    controller.listUsers(query);
    expect(adminService.listUsers).toHaveBeenCalledWith(query);
  });

  it('delegates Premium activation and platform stats', () => {
    controller.updatePremium('user-id', { isPremium: true });
    controller.getPlatformStats();
    expect(adminService.updatePremium).toHaveBeenCalledWith('user-id', { isPremium: true });
    expect(adminService.getPlatformStats).toHaveBeenCalled();
  });

  it('requires JWT and AdminGuard at controller level', () => {
    const guards = Reflect.getMetadata(GUARDS_METADATA, AdminController) as Function[];
    expect(guards).toContain(JwtAuthGuard);
    expect(guards).toContain(AdminGuard);
  });
});

import { Body, Controller, Delete, Get, HttpCode, HttpStatus, Param, ParseUUIDPipe, Patch, Post, Query, UseGuards } from '@nestjs/common';
import { ApiBearerAuth, ApiCreatedResponse, ApiNoContentResponse, ApiNotFoundResponse, ApiOkResponse, ApiOperation, ApiQuery, ApiResponse, ApiTags } from '@nestjs/swagger';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import type { CurrentUserPayload } from '../../common/decorators/current-user.decorator';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { AdminCommissionQueryDto, AdminMissionQueryDto, AdminUserQueryDto } from './dto/admin-query.dto';
import { AdminCommissionStatsDto } from './dto/admin-commission-stats.dto';
import { AdminMissionStatsDto } from './dto/admin-mission-stats.dto';
import { AdminCommissionListDto, AdminMissionListDto, AdminUserListDto } from './dto/admin-paginated.dto';
import { AdminMissionDto } from './dto/admin-mission.dto';
import { AdminUserDto } from './dto/admin-user.dto';
import { PlatformStatsDto } from './dto/platform-stats.dto';
import { AdminService } from './admin.service';
import { CreateMetierDto } from './dto/create-metier.dto';
import { CreateZoneDto } from './dto/create-zone.dto';
import { PatchSettingsDto } from './dto/patch-settings.dto';
import { UpdateMissionStatusDto } from './dto/update-mission-status.dto';
import { UpdatePremiumDto } from './dto/update-premium.dto';
import { UpdateMetierDto } from './dto/update-metier.dto';
import { UpdateZoneDto } from './dto/update-zone.dto';
import { UpdateUserStatusDto } from './dto/update-user-status.dto';
import { AdminGuard } from './admin.guard';

@ApiTags('Admin')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, AdminGuard)
@Controller('admin')
export class AdminController {
  constructor(private readonly adminService: AdminService) {}

  @Get('users')
  @ApiOperation({ summary: 'List and filter platform users' })
  @ApiOkResponse({ type: AdminUserListDto })
  @ApiQuery({ name: 'page', required: false, type: Number, example: 1 })
  @ApiQuery({ name: 'limit', required: false, type: Number, example: 20 })
  @ApiQuery({ name: 'role', required: false, enum: ['TRAVAILLEUR', 'RECRUTEUR', 'AGENT', 'ADMINISTRATEUR'] })
  @ApiQuery({ name: 'statut', required: false, enum: ['ACTIF', 'SUSPENDU', 'SUPPRIME'] })
  @ApiQuery({ name: 'premium', required: false, type: Boolean })
  @ApiQuery({ name: 'nom', required: false, type: String })
  @ApiQuery({ name: 'telephone', required: false, type: String })
  listUsers(@Query() query: AdminUserQueryDto) { return this.adminService.listUsers(query); }

  @Get('users/:id')
  @ApiOperation({ summary: 'Get a user account' })
  @ApiOkResponse({ type: AdminUserDto })
  @ApiNotFoundResponse({ description: 'User not found' })
  getUser(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string) { return this.adminService.getUser(id); }

  @Patch('users/:id/status')
  @ApiOperation({ summary: 'Change a user account status and notify the user' })
  @ApiOkResponse({ type: AdminUserDto })
  @ApiNotFoundResponse({ description: 'User not found' })
  updateUserStatus(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string, @Body() dto: UpdateUserStatusDto) {
    return this.adminService.updateUserStatus(id, dto);
  }

  @Patch('users/:id/premium')
  @ApiOperation({ summary: 'Manually activate or deactivate Premium for a user' })
  @ApiOkResponse({ type: AdminUserDto, example: { id: 'c3ac3a1a-2db1-4ef2-a058-7a2c31d1ad61', nom: 'Kouassi Jean', role: 'TRAVAILLEUR', statut: 'ACTIF', isPremium: true } })
  @ApiNotFoundResponse({ description: 'User not found' })
  updatePremium(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string, @Body() dto: UpdatePremiumDto) {
    return this.adminService.updatePremium(id, dto);
  }

  @Get('missions')
  @ApiOperation({ summary: 'List missions with status, date, and zone filters' })
  @ApiOkResponse({ type: AdminMissionListDto })
  @ApiQuery({ name: 'page', required: false, type: Number })
  @ApiQuery({ name: 'limit', required: false, type: Number })
  @ApiQuery({ name: 'statut', required: false, enum: ['BROUILLON', 'PUBLIEE', 'PARTIELLEMENT_POURVUE', 'POURVUE', 'EN_COURS', 'TERMINEE', 'ANNULEE', 'EXPIREE', 'SUSPENDUE', 'CLOTUREE'] })
  @ApiQuery({ name: 'date', required: false, type: String, format: 'date' })
  @ApiQuery({ name: 'zoneId', required: false, type: String, format: 'uuid' })
  listMissions(@Query() query: AdminMissionQueryDto) { return this.adminService.listMissions(query); }

  @Get('missions/stats')
  @ApiOperation({ summary: 'Get mission totals and grouped status statistics' })
  @ApiOkResponse({ type: AdminMissionStatsDto })
  getMissionStats() { return this.adminService.getMissionStats(); }

  @Get('missions/:id')
  @ApiOperation({ summary: 'Get a mission detail for administration' })
  @ApiOkResponse({ type: AdminMissionDto })
  @ApiNotFoundResponse({ description: 'Mission not found' })
  getMission(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string) { return this.adminService.getMission(id); }

  @Patch('missions/:id/status')
  @ApiOperation({ summary: 'Change a mission status and record its status history' })
  @ApiNotFoundResponse({ description: 'Mission not found' })
  updateMissionStatus(
    @CurrentUser() user: CurrentUserPayload,
    @Param('id', new ParseUUIDPipe({ version: '4' })) id: string,
    @Body() dto: UpdateMissionStatusDto,
  ) {
    return this.adminService.updateMissionStatus(id, dto, user.id);
  }

  @Get('commissions')
  @ApiOperation({ summary: 'List generated commissions and outstanding amounts' })
  @ApiOkResponse({ type: AdminCommissionListDto })
  @ApiQuery({ name: 'page', required: false, type: Number })
  @ApiQuery({ name: 'limit', required: false, type: Number })
  @ApiQuery({ name: 'workerId', required: false, type: String, format: 'uuid' })
  @ApiQuery({ name: 'missionId', required: false, type: String, format: 'uuid' })
  listCommissions(@Query() query: AdminCommissionQueryDto) { return this.adminService.listCommissions(query); }

  @Get('commissions/stats')
  @ApiOperation({ summary: 'Get generated, paid, and outstanding commission totals' })
  @ApiOkResponse({ type: AdminCommissionStatsDto })
  getCommissionStats() { return this.adminService.getCommissionStats(); }

  @Get('restricted-workers')
  @ApiOperation({ summary: 'List workers whose outstanding commission exceeds MAX_COMMISSION_DEBT' })
  @ApiQuery({ name: 'page', required: false, type: Number })
  @ApiQuery({ name: 'limit', required: false, type: Number })
  getRestrictedWorkers(@Query('page') page?: string, @Query('limit') limit?: string) {
    return this.adminService.getRestrictedWorkers(Number(page ?? 1), Number(limit ?? 20));
  }

  @Get('jobs')
  @ApiOperation({ summary: 'List job references' })
  listJobs() { return this.adminService.listJobs(); }

  @Post('jobs')
  @ApiOperation({ summary: 'Create a centrally managed job reference' })
  @ApiCreatedResponse({ description: 'Job reference created' })
  createJob(@Body() dto: CreateMetierDto) { return this.adminService.createJob(dto); }

  @Patch('jobs/:id')
  @ApiOperation({ summary: 'Update a centrally managed job reference or its active flag' })
  @ApiOkResponse({ description: 'Job reference updated' })
  @ApiNotFoundResponse({ description: 'Job reference not found' })
  updateJob(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string, @Body() dto: UpdateMetierDto) {
    return this.adminService.updateJob(id, dto);
  }

  @Delete('jobs/:id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiNoContentResponse({ description: 'Job soft-deleted' })
  deleteJob(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string) { return this.adminService.deleteJob(id); }

  @Get('zones')
  @ApiOperation({ summary: 'List geographic zones' })
  @ApiOkResponse({ description: 'Geographic zone references' })
  listZones() { return this.adminService.listZones(); }

  @Post('zones')
  @ApiOperation({ summary: 'Create a geographic zone' })
  @ApiCreatedResponse({ description: 'Zone created' })
  createZone(@Body() dto: CreateZoneDto) { return this.adminService.createZone(dto); }

  @Patch('zones/:id')
  @ApiOperation({ summary: 'Update a geographic zone' })
  @ApiOkResponse({ description: 'Zone updated' })
  @ApiNotFoundResponse({ description: 'Zone or parent zone not found' })
  updateZone(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string, @Body() dto: UpdateZoneDto) {
    return this.adminService.updateZone(id, dto);
  }

  @Delete('zones/:id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiNoContentResponse({ description: 'Zone soft-deleted' })
  deleteZone(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string) { return this.adminService.deleteZone(id); }

  @Get('settings')
  @ApiOperation({ summary: 'Get effective commission settings and platform values' })
  @ApiOkResponse({ example: { commissionPercent: 10, maxCommissionDebt: 5000, settings: [] } })
  listSettings() { return this.adminService.getSettings(); }

  @Patch('settings')
  @ApiOperation({ summary: 'Persist commission percentage and maximum debt settings' })
  @ApiOkResponse({ example: { commissionPercent: 10, maxCommissionDebt: 5000, settings: [] } })
  patchSettings(@Body() dto: PatchSettingsDto) {
    return this.adminService.patchSettings(dto);
  }

  @Get('platform-stats')
  @ApiOperation({ summary: 'Get platform-wide user, mission, application, commission, and notification statistics' })
  @ApiOkResponse({
    type: PlatformStatsDto,
    example: {
      usersTotal: 1405,
      workersTotal: 1200,
      recruitersTotal: 160,
      agentsTotal: 45,
      premiumUsers: 150,
      missionsPublished: 72,
      missionsCompleted: 850,
      applicationsTotal: 4300,
      commissionsGenerated: 12000000,
      commissionsOutstanding: 12000000,
      notificationsSent: 23500,
      whatsappMessagesSent: 9700,
    },
  })
  getPlatformStats() {
    return this.adminService.getPlatformStats();
  }
}

import { CanActivate, ExecutionContext, ForbiddenException, Injectable } from '@nestjs/common';
import { RoleEnum } from '@prisma/client';
import { CurrentUserPayload } from '../../common/decorators/current-user.decorator';

interface AdminRequest {
  user?: CurrentUserPayload;
}

@Injectable()
export class AdminGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<AdminRequest>();
    if (request.user?.role !== RoleEnum.ADMINISTRATEUR) {
      throw new ForbiddenException('Administrator role required');
    }
    return true;
  }
}

import { Module } from '@nestjs/common';
import { AdminController } from './admin.controller';
import { AdminService } from './admin.service';
import { AdminGuard } from './admin.guard';

@Module({ controllers: [AdminController], providers: [AdminService, AdminGuard] })
export class AdminModule {}

import { ForbiddenException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { RoleEnum, StatutCompteEnum, StatutMessageEnum, StatutMissionEnum } from '@prisma/client';
import { PrismaService } from '../../prisma/prisma.service';
import { CommissionsService } from '../commissions/commissions.service';
import { CommissionPolicyService } from '../commissions/commission-policy.service';
import { WorkerRestrictionService } from '../commissions/worker-restriction.service';
import { AdminGuard } from './admin.guard';
import { AdminService } from './admin.service';
import { UpdateUserStatusDto } from './dto/update-user-status.dto';

describe('AdminService', () => {
  const transaction = {
    profiles: { findUnique: jest.fn(), update: jest.fn() },
    notifications: { create: jest.fn() },
    notificationEvents: { create: jest.fn() },
  };
  const prisma = {
    $queryRaw: jest.fn(),
    $transaction: jest.fn((input: unknown) => Array.isArray(input)
      ? Promise.all(input as Promise<unknown>[])
      : (input as (tx: typeof transaction) => Promise<unknown>)(transaction)),
    profiles: { count: jest.fn(), findUnique: jest.fn(), update: jest.fn() },
    travailleurs: { count: jest.fn(), findMany: jest.fn() },
    recruteurs: { count: jest.fn() },
    agents: { count: jest.fn() },
    missions: { count: jest.fn(), groupBy: jest.fn(), findMany: jest.fn(), findFirst: jest.fn() },
    candidatures: { count: jest.fn() },
    commissions: { findMany: jest.fn(), count: jest.fn(), aggregate: jest.fn(), groupBy: jest.fn() },
    notifications: { count: jest.fn() },
    metiers: { findMany: jest.fn(), create: jest.fn(), findFirst: jest.fn(), update: jest.fn() },
    zones: { findMany: jest.fn(), create: jest.fn(), findFirst: jest.fn(), update: jest.fn() },
    platformSettings: { findMany: jest.fn(), upsert: jest.fn() },
  };
  const config = { get: jest.fn() };
  const commissionService = { getPlatformSummary: jest.fn() };
  const policy = { getMaxCommissionDebt: jest.fn() };
  const restrictions = { getRestrictedWorkersCount: jest.fn() };
  let service: AdminService;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new AdminService(
      prisma as unknown as PrismaService,
      config as unknown as ConfigService,
      commissionService as unknown as CommissionsService,
      policy as unknown as CommissionPolicyService,
      restrictions as unknown as WorkerRestrictionService,
    );
    transaction.profiles.findUnique.mockResolvedValue({ id: 'user-id', statut: StatutCompteEnum.ACTIF });
    transaction.profiles.update.mockResolvedValue({});
    transaction.notifications.create.mockResolvedValue({});
    transaction.notificationEvents.create.mockResolvedValue({});
    prisma.$queryRaw.mockResolvedValue([]);
    prisma.missions.count.mockResolvedValue(0);
    prisma.missions.groupBy.mockResolvedValue([]);
    prisma.candidatures.count.mockResolvedValue(0);
    prisma.profiles.count.mockResolvedValue(0);
    prisma.travailleurs.count.mockResolvedValue(0);
    prisma.recruteurs.count.mockResolvedValue(0);
    prisma.agents.count.mockResolvedValue(0);
    prisma.notifications.count.mockResolvedValue(0);
    prisma.commissions.aggregate.mockResolvedValue({ _sum: { montantCommission: null } });
    prisma.commissions.count.mockResolvedValue(0);
    prisma.commissions.findMany.mockResolvedValue([]);
    prisma.commissions.groupBy.mockResolvedValue([]);
    prisma.travailleurs.findMany.mockResolvedValue([]);
    prisma.platformSettings.findMany.mockResolvedValue([]);
    prisma.platformSettings.upsert.mockResolvedValue({});
    config.get.mockReturnValue(undefined);
    commissionService.getPlatformSummary.mockResolvedValue({
      totalCommissionsGenerated: 0n,
      totalCommissionsPaid: 0n,
      totalCommissionsOutstanding: 0n,
    });
    policy.getMaxCommissionDebt.mockResolvedValue(5000n);
    restrictions.getRestrictedWorkersCount.mockResolvedValue(0);
  });

  it('updates account status and creates a notification addressed only to that user', async () => {
    const dto: UpdateUserStatusDto = { statut: StatutCompteEnum.SUSPENDU };
    const user = {
      id: 'user-id', nom: 'Kouassi Jean', telephone: null,
      role: RoleEnum.TRAVAILLEUR, statut: StatutCompteEnum.SUSPENDU,
      isPremium: false, createdAt: new Date('2026-01-01T00:00:00.000Z'),
    };
    prisma.$queryRaw.mockResolvedValue([user]);

    await service.updateUserStatus('user-id', dto);
    expect(transaction.profiles.update).toHaveBeenCalledWith({ where: { id: 'user-id' }, data: { statut: dto.statut } });
    expect(transaction.notifications.create).toHaveBeenCalledWith({
      data: expect.objectContaining({ utilisateurId: 'user-id', type: 'ACCOUNT_STATUS_UPDATED' }),
    });
    expect(transaction.notificationEvents.create).toHaveBeenCalledWith({
      data: expect.objectContaining({ status: StatutMessageEnum.ENVOYE }),
    });
  });

  it('activates Premium through a profile update', async () => {
    const premiumUser = {
      id: 'user-id', nom: 'Kouassi Jean', telephone: null,
      role: RoleEnum.TRAVAILLEUR, statut: StatutCompteEnum.ACTIF,
      isPremium: true, createdAt: new Date('2026-01-01T00:00:00.000Z'),
    };
    prisma.profiles.findUnique.mockResolvedValue({ deletedAt: null });
    prisma.profiles.update.mockResolvedValue(premiumUser);

    await expect(service.updatePremium('user-id', { isPremium: true })).resolves.toMatchObject({ isPremium: true });
    expect(prisma.profiles.update).toHaveBeenCalledWith(expect.objectContaining({
      where: { id: 'user-id' },
      data: { isPremium: true },
    }));
  });

  it('returns platform statistics with commissions and restriction counts', async () => {
    prisma.profiles.count.mockResolvedValue(10);
    prisma.travailleurs.count.mockResolvedValue(6);
    prisma.recruteurs.count.mockResolvedValue(2);
    prisma.agents.count.mockResolvedValue(2);
    prisma.$queryRaw.mockResolvedValue([{ total: 3n }]);
    prisma.missions.count
      .mockResolvedValueOnce(4)
      .mockResolvedValueOnce(5);
    prisma.candidatures.count.mockResolvedValue(20);
    prisma.notifications.count.mockResolvedValueOnce(40).mockResolvedValueOnce(10);
    commissionService.getPlatformSummary.mockResolvedValue({
      totalCommissionsGenerated: 250000n,
      totalCommissionsPaid: 0n,
      totalCommissionsOutstanding: 250000n,
    });

    await expect(service.getPlatformStats()).resolves.toEqual({
      usersTotal: 10,
      workersTotal: 6,
      recruitersTotal: 2,
      agentsTotal: 2,
      premiumUsers: 3,
      missionsPublished: 4,
      missionsCompleted: 5,
      applicationsTotal: 20,
      commissionsGenerated: 250000,
      commissionsOutstanding: 250000,
      notificationsSent: 40,
      whatsappMessagesSent: 10,
    });
    expect(restrictions.getRestrictedWorkersCount).not.toHaveBeenCalled();
  });

  it('lists only workers above the configured debt threshold', async () => {
    prisma.commissions.groupBy.mockResolvedValue([
      { travailleurId: 'worker-1', _sum: { montantCommission: 5001n } },
      { travailleurId: 'worker-2', _sum: { montantCommission: 1000n } },
    ]);
    prisma.travailleurs.findMany.mockResolvedValue([{
      userId: 'worker-1', user: { nom: 'Kouassi Jean', telephone: '+2250701020304' },
    }]);

    await expect(service.getRestrictedWorkers()).resolves.toMatchObject({
      total: 1,
      data: [{ workerId: 'worker-1', remainingCommission: 5001, accountRestricted: true }],
    });
  });
});

describe('AdminGuard', () => {
  const guard = new AdminGuard();

  it('allows only an administrator request', () => {
    const context = {
      switchToHttp: () => ({ getRequest: () => ({ user: { id: 'admin-id', role: RoleEnum.ADMINISTRATEUR } }) }),
    } as never;
    expect(guard.canActivate(context)).toBe(true);
  });

  it('forbids non-admin roles', () => {
    const context = {
      switchToHttp: () => ({ getRequest: () => ({ user: { id: 'worker-id', role: RoleEnum.TRAVAILLEUR } }) }),
    } as never;
    expect(() => guard.canActivate(context)).toThrow(ForbiddenException);
  });
});

