    expect(controller.login(dto)).toEqual({ accessToken: 'access', refreshToken: 'refresh', expiresIn: 3600 });
    expect(authService.login).toHaveBeenCalledWith(dto);
  });

  it('passes the current Supabase bearer token to logout', () => {
    authService.logout.mockReturnValue({ message: 'Logged out successfully' });

    expect(controller.logout('Bearer access-token')).toEqual({ message: 'Logged out successfully' });
    expect(authService.logout).toHaveBeenCalledWith('access-token');
  });

  it('passes the guard-hydrated user to AuthService.me', () => {
    const user: CurrentUserPayload = {
      id: 'auth-user-id',
      email: 'worker@example.com',
      role: RoleEnum.TRAVAILLEUR,
    };
    authService.me.mockReturnValue({ id: user.id, role: user.role });

    expect(controller.me(user)).toEqual({ id: user.id, role: user.role });
    expect(authService.me).toHaveBeenCalledWith(user);
  });
});

import { Body, Controller, Get, Headers, Post, UnauthorizedException, UseGuards } from '@nestjs/common';
import { ApiBearerAuth, ApiOperation, ApiResponse, ApiTags } from '@nestjs/swagger';
import { SupabaseAuthGuard } from './guards/supabase-auth.guard';
import { AuthService } from './auth.service';
import { CurrentUser } from './decorators/current-user.decorator';
import { ForgotPasswordDto } from './dto/forgot-password.dto';
import { LoginDto } from './dto/login.dto';
import { RefreshTokenDto } from './dto/refresh-token.dto';
import { RegisterRecruiterDto } from './dto/register-recruiter.dto';
import { RegisterWorkerDto } from './dto/register-worker.dto';
import { ResetPasswordDto } from './dto/reset-password.dto';
import type { CurrentUserPayload } from './interfaces/current-user-payload.interface';

@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('register/worker')
  @ApiOperation({ summary: 'Register a worker through Supabase Auth' })
  @ApiResponse({ status: 201, description: 'Worker account created' })
  @ApiResponse({ status: 400, description: 'Invalid registration data' })
  @ApiResponse({ status: 404, description: 'Agent referral code not found' })
  @ApiResponse({ status: 409, description: 'Email or phone already exists' })
  registerWorker(@Body() dto: RegisterWorkerDto) {
    return this.authService.registerWorker(dto);
  }

  @Post('register/recruiter')
  @ApiOperation({ summary: 'Register a recruiter through Supabase Auth' })
  @ApiResponse({ status: 201, description: 'Recruiter account created' })
  @ApiResponse({ status: 400, description: 'Invalid registration data' })
  @ApiResponse({ status: 409, description: 'Email or phone already exists' })
  registerRecruiter(@Body() dto: RegisterRecruiterDto) {
    return this.authService.registerRecruiter(dto);
  }

  @Post('login')
  @ApiOperation({ summary: 'Authenticate through Supabase Auth' })
  @ApiResponse({ status: 200, description: 'Access and refresh tokens' })
  @ApiResponse({ status: 401, description: 'Invalid credentials' })
  login(@Body() dto: LoginDto) {
    return this.authService.login(dto);
  }

  @Post('logout')
  @UseGuards(SupabaseAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Revoke the current Supabase session' })
  @ApiResponse({ status: 200, description: 'Session revoked' })
  @ApiResponse({ status: 401, description: 'Missing or invalid access token' })
  logout(@Headers('authorization') authorization?: string) {
    const token = authorization?.match(/^Bearer\s+(\S+)$/i)?.[1];
    if (!token) throw new UnauthorizedException('Bearer access token is required');
    return this.authService.logout(token);
  }

  @Post('refresh')
  @ApiOperation({ summary: 'Refresh a Supabase session' })
  @ApiResponse({ status: 200, description: 'New access and refresh tokens' })
  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
  refresh(@Body() dto: RefreshTokenDto) {
    return this.authService.refresh(dto);
  }

  @Post('forgot-password')
  @ApiOperation({ summary: 'Send a password reset email' })
  @ApiResponse({ status: 200, description: 'Password reset request accepted' })
  @ApiResponse({ status: 400, description: 'Invalid email' })
  forgotPassword(@Body() dto: ForgotPasswordDto) {
    return this.authService.forgotPassword(dto);
  }

  @Post('reset-password')
  @ApiOperation({ summary: 'Set a new password using a recovery token' })
  @ApiResponse({ status: 200, description: 'Password updated' })
  @ApiResponse({ status: 400, description: 'Invalid recovery token or password confirmation' })
  resetPassword(@Body() dto: ResetPasswordDto) {
    return this.authService.resetPassword(dto);
  }

  @Get('me')
  @UseGuards(SupabaseAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Get the authenticated XeuySil profile' })
  @ApiResponse({ status: 200, description: 'Authenticated profile' })
  @ApiResponse({ status: 401, description: 'Missing or invalid access token' })
  me(@CurrentUser() user: CurrentUserPayload) {
    return this.authService.me(user);
  }
}

import { NotFoundException } from '@nestjs/common';
import { RoleEnum } from '@prisma/client';
import { PrismaService } from '../../prisma/prisma.service';
import { AuthService } from './auth.service';
import { CurrentUserPayload } from './interfaces/current-user-payload.interface';
import { SupabaseService } from './services/supabase.service';
import { RegisterWorkerDto } from './dto/register-worker.dto';
import { RegisterRecruiterDto } from './dto/register-recruiter.dto';

describe('AuthService', () => {
  const transaction = {
    agents: { findUnique: jest.fn() },
    profiles: { create: jest.fn() },
    travailleurs: { create: jest.fn() },
    recruteurs: { create: jest.fn() },
  };
  const prisma = {
    $transaction: jest.fn((callback: (tx: typeof transaction) => Promise<unknown>) => callback(transaction)),
    profiles: { findUnique: jest.fn() },
  };
  const supabase = {
    createUser: jest.fn(),
    deleteUser: jest.fn(),
    login: jest.fn(),
    logout: jest.fn(),
    refresh: jest.fn(),
    sendPasswordReset: jest.fn(),
    resetPassword: jest.fn(),
  };
  const notifications = { notifyAgentWorkerCreated: jest.fn() };
  let service: AuthService;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new AuthService(
      prisma as unknown as PrismaService,
      supabase as unknown as SupabaseService,
      notifications as never,
    );
    supabase.createUser.mockResolvedValue({ id: 'auth-user-id', email: 'worker@example.com' });
    supabase.deleteUser.mockResolvedValue(undefined);
    transaction.agents.findUnique.mockResolvedValue(null);
    transaction.profiles.create.mockResolvedValue({});
    transaction.travailleurs.create.mockResolvedValue({});
