import { BadRequestException, Injectable } from '@nestjs/common';
import { CanalEnum, Prisma, StatutMessageEnum } from '@prisma/client';
import { randomUUID } from 'crypto';
import { isUUID } from 'class-validator';

export const NOTIFICATION_TYPES = [
  'MISSION_PROPOSEE',
  'MISSION_SELECTIONNEE',
  'MISSION_CONFIRMEE',
  'MISSION_REJETEE',
  'MISSION_ANNULEE',
  'MISSION_POURVUE',
  'NOUVELLE_CANDIDATURE',
  'TRAVAILLEUR_INSCRIT',
  'TRAVAILLEUR_SELECTIONNE',
  'TRAVAILLEUR_ABSENT',
  'COMMISSION_DUE',
  'COMMISSION_REMINDER',
  'COMMISSION_BLOCKED',
] as const;

export type NotificationType = typeof NOTIFICATION_TYPES[number];

export interface NotificationFactoryInput {
  recipientUserId: string;
  type: NotificationType;
  missionId?: string | null;
  payload: Prisma.InputJsonObject;
}

@Injectable()
export class NotificationFactory {
  createNotification(input: NotificationFactoryInput): Prisma.NotificationsUncheckedCreateInput {
    if (!isUUID(input.recipientUserId)) {
      throw new BadRequestException('A valid notification recipient user ID is required');
    }

    return {
      id: randomUUID(),
      utilisateurId: input.recipientUserId,
      missionId: input.missionId ?? null,
      type: input.type,
      canal: CanalEnum.APPLICATION,
      statut: StatutMessageEnum.EN_FILE,
      lu: false,
    };
  }

  createEvent(
    notificationId: string,
    status: StatutMessageEnum,
    payload: Prisma.InputJsonObject,
  ): Prisma.NotificationEventsUncheckedCreateInput {
    return {
      id: randomUUID(),
      notificationId,
      status,
      payload,
    };
  }
}

import { GUARDS_METADATA } from '@nestjs/common/constants';
import { RoleEnum } from '@prisma/client';
import { ROLES_METADATA_KEY } from '../../common/constants/roles.constant';
import type { CurrentUserPayload } from '../../common/decorators/current-user.decorator';
import { RolesGuard } from '../../common/guards/roles.guard';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { MissionBroadcastDto } from './dto/mission-broadcast.dto';
import { NotificationQueryDto } from './dto/notification-query.dto';
import { NotificationsController } from './notifications.controller';
import { NotificationsService } from './notifications.service';

describe('NotificationsController', () => {
  const notificationsService = {
    list: jest.fn(),
    getById: jest.fn(),
    markRead: jest.fn(),
    markAllRead: jest.fn(),
    unreadCount: jest.fn(),
    broadcastMission: jest.fn(),
  };
  const worker: CurrentUserPayload = {
    id: 'c3ac3a1a-2db1-4ef2-a058-7a2c31d1ad61',
    email: 'worker@example.com',
    role: RoleEnum.TRAVAILLEUR,
  };
  const recruiter: CurrentUserPayload = {
    id: 'c3ac3a1a-2db1-4ef2-a058-7a2c31d1ad62',
    email: 'recruiter@example.com',
    role: RoleEnum.RECRUTEUR,
  };
  let controller: NotificationsController;

  beforeEach(() => {
    jest.clearAllMocks();
    controller = new NotificationsController(notificationsService as unknown as NotificationsService);
  });

  it('scopes paginated listing, detail, and read operations to the authenticated user', async () => {
    const query: NotificationQueryDto = { page: 2, limit: 10, lu: false };
    notificationsService.list.mockResolvedValue({ data: [], page: 2, limit: 10, total: 0, totalPages: 0 });
    notificationsService.getById.mockResolvedValue({ id: 'notification-id' });
    notificationsService.markRead.mockResolvedValue({ id: 'notification-id', lu: true });
    notificationsService.markAllRead.mockResolvedValue({ count: 2 });
    notificationsService.unreadCount.mockResolvedValue(8);

    await controller.list(worker, query);
    await controller.getById(worker, 'notification-id');
    await controller.markRead(worker, 'notification-id');
    await controller.markAllRead(worker);
    await controller.unreadCount(worker);

    expect(notificationsService.list).toHaveBeenCalledWith(worker.id, query);
    expect(notificationsService.getById).toHaveBeenCalledWith(worker.id, 'notification-id');
    expect(notificationsService.markRead).toHaveBeenCalledWith(worker.id, 'notification-id');
    expect(notificationsService.markAllRead).toHaveBeenCalledWith(worker.id);
    expect(notificationsService.unreadCount).toHaveBeenCalledWith(worker.id);
  });

  it('passes the recruiter identity and selected recipients to mission broadcast', () => {
    const dto: MissionBroadcastDto = {
      missionId: 'c3ac3a1a-2db1-4ef2-a058-7a2c31d1ad63',
      workerIds: ['c3ac3a1a-2db1-4ef2-a058-7a2c31d1ad64'],
    };
    notificationsService.broadcastMission.mockReturnValue({ workersNotified: 1 });

    expect(controller.broadcastMission(recruiter, dto)).toEqual({ workersNotified: 1 });
    expect(notificationsService.broadcastMission).toHaveBeenCalledWith(recruiter.id, dto);
  });

  it('requires JWT on every route and the recruiter role on broadcast', () => {
    const controllerGuards = Reflect.getMetadata(GUARDS_METADATA, NotificationsController) as Function[];
    const broadcastGuards = Reflect.getMetadata(GUARDS_METADATA, controller.broadcastMission) as Function[];

    expect(controllerGuards).toContain(JwtAuthGuard);
    expect(broadcastGuards).toContain(RolesGuard);
    expect(Reflect.getMetadata(ROLES_METADATA_KEY, controller.broadcastMission)).toEqual([RoleEnum.RECRUTEUR]);
  });
});

import { Body, Controller, Get, HttpCode, HttpStatus, Param, ParseUUIDPipe, Patch, Post, Query, UseGuards } from '@nestjs/common';
import { ApiBearerAuth, ApiCreatedResponse, ApiNoContentResponse, ApiNotFoundResponse, ApiOkResponse, ApiOperation, ApiQuery, ApiResponse, ApiTags } from '@nestjs/swagger';
import { RoleEnum } from '@prisma/client';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import type { CurrentUserPayload } from '../../common/decorators/current-user.decorator';
import { Roles } from '../../common/decorators/roles.decorator';
import { RolesGuard } from '../../common/guards/roles.guard';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { MissionBroadcastDto } from './dto/mission-broadcast.dto';
import { MissionBroadcastResponseDto } from './dto/mission-broadcast-response.dto';
import { NotificationDetailsDto } from './dto/notification-details.dto';
import { NotificationListDto } from './dto/notification-list.dto';
import { NotificationQueryDto } from './dto/notification-query.dto';
import { UnreadCountDto } from './dto/unread-count.dto';
import { NotificationsService } from './notifications.service';

@ApiTags('Notifications')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('notifications')
export class NotificationsController {
  constructor(private readonly notificationsService: NotificationsService) {}

  @Get()
  @ApiOperation({ summary: 'List only the authenticated user notifications' })
  @ApiOkResponse({ type: NotificationListDto, example: { data: [], page: 1, limit: 20, total: 0, totalPages: 0 } })
  @ApiQuery({ name: 'page', required: false, type: Number, example: 1 })
  @ApiQuery({ name: 'limit', required: false, type: Number, example: 20, description: 'Maximum 100' })
  @ApiQuery({ name: 'lu', required: false, type: Boolean, example: false })
  list(@CurrentUser() user: CurrentUserPayload, @Query() query: NotificationQueryDto) {
    return this.notificationsService.list(user.id, query);
  }

  @Get('unread-count')
  @ApiOperation({ summary: 'Count unread notifications for the authenticated user' })
  @ApiOkResponse({ type: UnreadCountDto, example: { count: 8 } })
  async unreadCount(@CurrentUser() user: CurrentUserPayload) {
    return { count: await this.notificationsService.unreadCount(user.id) };
  }

  @Patch('read-all')
  @ApiOperation({ summary: 'Mark all authenticated user notifications as read' })
  @ApiOkResponse({ example: { count: 8 } })
  markAllRead(@CurrentUser() user: CurrentUserPayload) {
    return this.notificationsService.markAllRead(user.id);
  }

  @Post('mission-broadcast')
  @UseGuards(RolesGuard)
  @Roles(RoleEnum.RECRUTEUR)
  @ApiOperation({ summary: 'Send a mission proposal to up to 15 selected compatible workers and their agents' })
  @ApiCreatedResponse({ type: MissionBroadcastResponseDto })
  @ApiResponse({ status: 400, description: 'Invalid, incompatible, or more than 15 worker recipients' })
  @ApiResponse({ status: 403, description: 'Mission does not belong to this recruiter' })
  @ApiResponse({
    status: 403,
    description: 'COMMISSION_PAYMENT_REQUIRED: A selected worker has outstanding commissions above the configured limit.',
  })
  @ApiNotFoundResponse({ description: 'Mission not found' })
  @ApiResponse({ status: 409, description: 'Mission is not active for broadcast' })
  broadcastMission(@CurrentUser() user: CurrentUserPayload, @Body() dto: MissionBroadcastDto) {
    return this.notificationsService.broadcastMission(user.id, dto);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get one notification owned by the authenticated user, including events' })
  @ApiOkResponse({ type: NotificationDetailsDto })
  @ApiNotFoundResponse({ description: 'Notification not found' })
  getById(@CurrentUser() user: CurrentUserPayload, @Param('id', new ParseUUIDPipe({ version: '4' })) id: string) {
    return this.notificationsService.getById(user.id, id);
  }

  @Patch(':id/read')
  @ApiOperation({ summary: 'Mark an owned notification as read and record a LU event' })
  @ApiOkResponse({ type: NotificationDetailsDto })
  @ApiNotFoundResponse({ description: 'Notification not found' })
  markRead(@CurrentUser() user: CurrentUserPayload, @Param('id', new ParseUUIDPipe({ version: '4' })) id: string) {
    return this.notificationsService.markRead(user.id, id);
  }
}

